const fs = require('fs');
const path = require('path');

const rawAi = $input.first().json;
const candidateText = rawAi.candidates?.[0]?.content?.parts?.[0]?.text;
if (!candidateText) {
  throw new Error('Gemini did not return candidates: ' + JSON.stringify(rawAi));
}

const aiData = JSON.parse(candidateText);
const prepData = $('Load Profile & Prepare Input').first().json;
const job = prepData.job;
const profile = prepData.profile;

// Generate Application Document ID
const appId = `${job.company_name.toLowerCase().replace(/[^a-z0-9]/g, '_')}_${Date.now()}`;

// Hydrate CV HTML (1-PAGE STRICT)
const p = profile.personal || {};
const summary = aiData.tailored_summary || (typeof profile.summary === 'object' ? profile.summary.fr : profile.summary) || '';
const headline = aiData.target_headline || p.headline || 'Junior Data Engineer | Software Engineer';

// Skills Rows (Compact)
let skillsHtml = '';
const categoryLabels = {
  data_engineering: 'Data Engineering',
  languages: 'Langages',
  cloud_and_devops: 'Cloud & DevOps',
  frameworks_and_backend: 'Frameworks & Web',
  databases: 'Bases de données',
  ai_and_analytics: 'Analytics & IA',
  tools_and_methods: 'Outils & Méthodes'
};
for (const [key, items] of Object.entries(profile.skills || {})) {
  if (Array.isArray(items) && items.length > 0) {
    const label = categoryLabels[key] || key.replace(/_/g, ' ');
    skillsHtml += `<div class="skill-row"><span class="skill-label">${label} :</span><span class="skill-values">${items.join(', ')}</span></div>`;
  }
}

// Experiences (Top 3)
const experiences = (profile.experience || []).slice(0, 3);
let expHtml = '';
for (let i = 0; i < experiences.length; i++) {
  const exp = experiences[i];
  const aiExp = (aiData.tailored_experience || []).find(e => e.company === exp.company) || {};
  const bullets = (aiExp.bullets || exp.bullets || []).slice(0, 3);
  const bulletsHtml = bullets.map(b => `<li>${b}</li>`).join('\n');
  expHtml += `
    <div class="entry">
      <div class="entry-header">
        <div>
          <span class="entry-title">${exp.title.split('/')[0].trim()}</span> | 
          <span class="entry-company">${exp.company}</span>
          <span style="color: #64748b; font-size: 7.8pt;">(${exp.location || ''})</span>
        </div>
        <span class="entry-date">${exp.start_date.split('/')[0].trim()} – ${exp.end_date.split('/')[0].trim()}</span>
      </div>
      <ul class="entry-bullets">${bulletsHtml}</ul>
    </div>`;
}

// Projects (Top 2)
let projHtml = '';
const projects = (profile.projects || []).slice(0, 2);
for (const proj of projects) {
  const tech = (proj.tech_stack || []).join(', ');
  projHtml += `
    <div class="entry">
      <div class="entry-header">
        <div>
          <span class="entry-title">${proj.name}</span>
          <span style="color: #64748b; font-size: 7.8pt;">| ${tech}</span>
        </div>
        <span class="entry-date">${(proj.date || '').split('/')[0].trim()}</span>
      </div>
      <ul class="entry-bullets">
        <li>${proj.description || ''}</li>
      </ul>
    </div>`;
}

// Education (EMSI & ISTA NTIC)
let eduHtml = '';
const education = (profile.education || []).slice(0, 2);
for (const edu of education) {
  const degreeShort = edu.degree.split('/')[0].trim();
  eduHtml += `
    <div class="entry">
      <div class="entry-header">
        <div>
          <span class="entry-title">${degreeShort}</span> | 
          <span class="entry-company">${edu.institution}</span>
        </div>
        <span class="entry-date">${edu.start_date} – ${edu.end_date}</span>
      </div>
    </div>`;
}

// Inline Certifications & Languages
const certsList = (profile.certifications || []).map(c => typeof c === 'string' ? c : `${c.name} (${c.issuer})`);
const certsInline = certsList.slice(0, 5).join(' • ');
const langsInline = (profile.personal?.languages || []).map(l => `${l.name} (${l.level.split('/')[0].trim()})`).join(' • ');

// Load templates
let cvTplPath = '/data/templates/cv_template.html';
let letterTplPath = '/data/templates/cover_letter_template.html';
if (!fs.existsSync(cvTplPath)) {
  cvTplPath = '/Users/abdelhakmirbah/Desktop/CVs/jobAssistant N8n/templates/cv_template.html';
  letterTplPath = '/Users/abdelhakmirbah/Desktop/CVs/jobAssistant N8n/templates/cover_letter_template.html';
}

let cvHtml = fs.readFileSync(cvTplPath, 'utf8')
  .replace(/{{FULL_NAME}}/g, p.full_name || '')
  .replace(/{{TARGET_HEADLINE}}/g, headline)
  .replace(/{{EMAIL}}/g, p.email || '')
  .replace(/{{PHONE}}/g, p.phone || '')
  .replace(/{{LOCATION}}/g, p.location || '')
  .replace(/{{LINKEDIN_DISPLAY}}/g, (p.linkedin || '').replace('https://', ''))
  .replace(/{{PORTFOLIO_DISPLAY}}/g, (p.portfolio || '').replace('https://', ''))
  .replace(/{{TAILORED_SUMMARY}}/g, summary)
  .replace(/{{SKILLS_ROWS}}/g, skillsHtml)
  .replace(/{{EXPERIENCE_ENTRIES}}/g, expHtml)
  .replace(/{{PROJECTS_ENTRIES}}/g, projHtml)
  .replace(/{{EDUCATION_ENTRIES}}/g, eduHtml)
  .replace(/{{CERTIFICATIONS_INLINE}}/g, certsInline)
  .replace(/{{LANGUAGES_INLINE}}/g, langsInline);

// Letter paragraphs
const letterParagraphs = (aiData.cover_letter?.paragraphs || []).map(p => `<p>${p}</p>`).join('\n');
const todayStr = new Date().toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' });

let letterHtml = fs.readFileSync(letterTplPath, 'utf8')
  .replace(/{{FULL_NAME}}/g, p.full_name || '')
  .replace(/{{TARGET_HEADLINE}}/g, headline)
  .replace(/{{EMAIL}}/g, p.email || '')
  .replace(/{{PHONE}}/g, p.phone || '')
  .replace(/{{LOCATION}}/g, p.location || '')
  .replace(/{{LINKEDIN_DISPLAY}}/g, (p.linkedin || '').replace('https://', ''))
  .replace(/{{COMPANY_NAME}}/g, job.company_name)
  .replace(/{{COMPANY_LOCATION}}/g, job.company_location)
  .replace(/{{JOB_TITLE}}/g, job.job_title)
  .replace(/{{TODAY_DATE}}/g, todayStr)
  .replace(/{{SALUTATION}}/g, aiData.cover_letter?.salutation || 'Madame, Monsieur,')
  .replace(/{{COVER_LETTER_PARAGRAPHS}}/g, letterParagraphs)
  .replace(/{{COMPLIMENTARY_CLOSE}}/g, aiData.cover_letter?.complimentary_close || 'Cordialement.');

return [{
  json: {
    app_id: appId,
    job: job,
    ai_data: aiData,
    cv_html: cvHtml,
    letter_html: letterHtml,
    created_at: new Date().toISOString()
  }
}];

